        @Override
        public boolean aplicavel(Pedido pedido) {
            return pedido.subtotal().compareTo(new BigDecimal("300")) >= 0;
        }

        @Override
        public BigDecimal desconto(Pedido pedido, BigDecimal frete) {
            return new BigDecimal("50");
        }
    },
    FRETEGRATIS {
        @Override
        public BigDecimal desconto(Pedido pedido, BigDecimal frete) {
            return frete;
        }
