17	import java.math.BigDecimal;
18	import java.util.ArrayList;
19	import java.util.List;
20	import java.util.Optional;
21	import org.springframework.stereotype.Service;
22	
23	@Service
24	public class CalculadoraResumo {
25	
26	    public ResumoResponse calcular(ResumoRequest req) {
27	        Pedido pedido = montarPedido(req.itens());
28	        NivelClube nivel = buscar(NivelClube.class, req.nivelClube(), "NIVEL_CLUBE_INVALIDO");
29	        Regiao regiao = buscar(Regiao.class, req.regiao(), "REGIAO_INVALIDA");
30	        Modalidade modalidade = buscar(Modalidade.class, req.modalidadeEntrega(), "MODALIDADE_INVALIDA");
31	        if (!modalidade.atende(pedido.peso())) {
32	            throw new ErroPedidoException("MODALIDADE_INDISPONIVEL");
33	        }
34	        Cupom cupom = cupomOpcional(req.cupom(), pedido);
35	        FormaPagamento forma = buscar(FormaPagamento.class, req.formaPagamento(), "FORMA_PAGAMENTO_INVALIDA");
36	        int parcelas = Optional.ofNullable(req.parcelas()).orElse(1);
37	        if (!forma.parcelasPermitidas(parcelas)) {
38	            throw new ErroPedidoException("PARCELAMENTO_INVALIDO");
39	        }
40	
41	        BigDecimal subtotal = pedido.subtotal();
42	        BigDecimal frete = Dinheiro.centavos(nivel.frete(modalidade.frete(pedido.peso())));
43	        BigDecimal desconto = cupom == null ? BigDecimal.ZERO : Dinheiro.centavos(cupom.desconto(pedido, frete));
44	        BigDecimal seguro = Dinheiro.centavos(subtotal.multiply(regiao.percentualSeguro()));
45	        BigDecimal total = subtotal.subtract(desconto).add(frete).add(seguro);
46	        if (!forma.disponivel(total)) {
47	            throw new ErroPedidoException("FORMA_PAGAMENTO_INDISPONIVEL");
48	        }
49	        Pagamento pagamento = forma.calcular(total, parcelas);
50	
51	        return new ResumoResponse(
52	                subtotal,
53	                desconto,
54	                frete,
55	                modalidade.prazoDias(),
56	                seguro,
57	                pagamento.totalFinal().subtract(total),
58	                pagamento.totalFinal(),
59	                pagamento.parcelas(),
60	                pagamento.valorParcela(),
61	                Dinheiro.centavos(nivel.credito(subtotal)),
62	                nivel.temBrinde(subtotal));
63	    }
64	
65	    private Pedido montarPedido(List<ItemRequest> itens) {
66	        if (itens == null || itens.isEmpty()) {
67	            throw new ErroPedidoException("PEDIDO_INVALIDO");
68	        }
69	        List<ItemPedido> resultado = new ArrayList<>();
70	        for (ItemRequest item : itens) {
71	            if (item == null
72	                    || item.precoUnitario() == null || item.precoUnitario().signum() <= 0
73	                    || item.quantidade() == null || item.quantidade() <= 0
74	                    || item.pesoKg() == null || item.pesoKg().signum() <= 0) {
75	                throw new ErroPedidoException("PEDIDO_INVALIDO");
76	            }
77	            resultado.add(new ItemPedido(item.precoUnitario(), item.quantidade(), item.pesoKg()));
78	        }
79	        return new Pedido(resultado);
80	    }
81	
82	    private Cupom cupomOpcional(String codigo, Pedido pedido) {
83	        if (codigo == null) {
84	            return null;
85	        }
86	        Cupom cupom = buscar(Cupom.class, codigo, "CUPOM_INVALIDO");
87	        if (!cupom.aplicavel(pedido)) {
88	            throw new ErroPedidoException("CUPOM_NAO_APLICAVEL");
89	        }
90	        return cupom;
91	    }
92	
93	    private static <E extends Enum<E>> E buscar(Class<E> tipo, String codigo, String erro) {
94	        return Codigos.buscar(tipo, codigo).orElseThrow(() -> new ErroPedidoException(erro));
95	    }
96	}
