6	public enum FormaPagamento {
7	
8	    PIX {
9	        @Override
10	        public boolean parcelasPermitidas(int parcelas) {
11	            return parcelas == 1;
12	        }
13	
14	        @Override
15	        public Pagamento calcular(BigDecimal total, int parcelas) {
16	            BigDecimal totalFinal = total.subtract(Dinheiro.centavos(total.multiply(new BigDecimal("0.05"))));
17	            return new Pagamento(Dinheiro.centavos(totalFinal), 1, Dinheiro.centavos(totalFinal));
18	        }
19	    },
20	    CARTAO {
21	        @Override
22	        public boolean parcelasPermitidas(int parcelas) {
23	            return parcelas >= 1 && parcelas <= 12;
24	        }
25	
26	        @Override
27	        public Pagamento calcular(BigDecimal total, int parcelas) {
28	            if (parcelas <= 3) {
29	                return new Pagamento(Dinheiro.centavos(total), parcelas,
30	                        Dinheiro.centavos(total.divide(BigDecimal.valueOf(parcelas), MathContext.DECIMAL128)));
31	            }
32	            BigDecimal taxaMensal = new BigDecimal("0.0199");
33	            BigDecimal inverso = BigDecimal.ONE.divide(BigDecimal.ONE.add(taxaMensal).pow(parcelas), MathContext.DECIMAL128);
34	            BigDecimal parcela = Dinheiro.centavos(total.multiply(taxaMensal)
35	                    .divide(BigDecimal.ONE.subtract(inverso), MathContext.DECIMAL128));
36	            return new Pagamento(parcela.multiply(BigDecimal.valueOf(parcelas)), parcelas, parcela);
37	        }
38	    },
