        assertEquals(new ResumoResponse(
                b("409.70"), b("40.97"), b("33.10"), 2, b("10.24"), b("-20.60"),
                b("391.47"), 1, b("391.47"), b("0.00"), false), calculadora.calcular(req));
    }

